import React, { useState } from 'react';
import './CSS/Products.css';
import smartphone from '../images/smartphone.j'

const productData = [
  {
    id: 1,
    name: 'Pro Max 15 (256GB)',
    category: 'Smartphones',
    price: 1199,
    oldPrice: 1299,
    rating: 4.9,
    badge: 'HOT',
    image: 'https://via.placeholder.com/200x220?text=Smartphone'
  },
  {
    id: 2,
    name: 'Wireless Noise-Canceling Earbuds',
    category: 'Audio',
    price: 199,
    oldPrice: 249,
    rating: 4.7,
    badge: 'SALE',
    image: 'https://via.placeholder.com/200x220?text=Earbuds'
  },
  {
    id: 3,
    name: 'Ultra Fit Smartwatch v2',
    category: 'Wearables',
    price: 299,
    oldPrice: null,
    rating: 4.8,
    badge: 'NEW',
    image: 'https://via.placeholder.com/200x220?text=Smartwatch'
  },
  {
    id: 4,
    name: 'Flagship Speed Phone X',
    category: 'Smartphones',
    price: 899,
    oldPrice: 999,
    rating: 4.6,
    badge: 'SALE',
    image: 'https://via.placeholder.com/200x220?text=Phone+X'
  },
  {
    id: 5,
    name: 'Fast-Charge Power Bank 20000mAh',
    category: 'Accessories',
    price: 49,
    oldPrice: 65,
    rating: 4.9,
    badge: null,
    image: 'https://via.placeholder.com/200x220?text=Powerbank'
  },
  {
    id: 6,
    name: 'Gaming Headset Surround 7.1',
    category: 'Audio',
    price: 129,
    oldPrice: 159,
    rating: 4.5,
    badge: 'HOT',
    image: 'https://via.placeholder.com/200x220?text=Headset'
  }
];

const Products = () => {
  const [selectedCategory, setSelectedCategory] = useState('All');

  const filteredProducts = selectedCategory === 'All' 
    ? productData 
    : productData.filter(item => item.category === selectedCategory);

  return (
    <div className='products-page'>
      {/* Top Header Banner */}
      <div className='products-header'>
        <h1>Explore All Gadgets</h1>
        <p>Discover top-tier mobile devices, wearables, and high-performance tech accessories.</p>
      </div>

      {/* Main Content Area */}
      <div className='products-container'>
        {/* Category Filters Bar */}
        <div className='products-filter-bar'>
          {['All', 'Smartphones', 'Audio', 'Wearables', 'Accessories'].map((cat) => (
            <button
              key={cat}
              className={`filter-btn ${selectedCategory === cat ? 'active' : ''}`}
              onClick={() => setSelectedCategory(cat)}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Product Grid */}
        <div className='products-grid'>
          {filteredProducts.map((product) => (
            <div key={product.id} className='product-card'>
              <div className='card-image-wrapper'>
                {product.badge && <span className={`card-badge ${product.badge.toLowerCase()}`}>{product.badge}</span>}
                <img src={product.image} alt={product.name} />
                <button className='add-to-cart-btn'>
                  <i className="fa-solid fa-cart-shopping"></i> Add to Cart
                </button>
              </div>

              <div className='card-info'>
                <span className='card-category'>{product.category}</span>
                <h3 className='card-title'>{product.name}</h3>

                <div className='card-rating'>
                  <i className="fa-solid fa-star"></i>
                  <span>{product.rating}</span>
                </div>

                <div className='card-price'>
                  <span className='current-price'>${product.price}</span>
                  {product.oldPrice && <span className='old-price'>${product.oldPrice}</span>}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Products;
